package com.bank.arrays;

import org.springframework.stereotype.Service;

@Service
public class ArrayReverseService {

    // ═══ TWO-POINTER SWAP — no inbuilt functions ═══
    public int[] reverse(int[] arr) {
        int left = 0;
        int right = arr.length - 1;
        while (left < right) {
            // Swap without temp variable (XOR) or with temp:
            int temp = arr[left];
            arr[left] = arr[right];
            arr[right] = temp;
            left++;
            right--;
        }
        return arr;
    }

    // Stream approach (creates new array — not in-place):
    public int[] reverseStream(int[] arr) {
        int n = arr.length;
        return java.util.stream.IntStream.range(0, n)
            .map(i -> arr[n - 1 - i])
            .toArray();
    }
}
