package com.bank.arrays;

import org.junit.jupiter.api.Test;
import static org.assertj.core.api.Assertions.*;

class ArrayReverseTest {

    ArrayReverseService service = new ArrayReverseService();

    @Test void reverseOddLength() {
        assertThat(service.reverse(new int[]{1, 2, 3, 4, 5}))
            .containsExactly(5, 4, 3, 2, 1);
    }

    @Test void reverseEvenLength() {
        assertThat(service.reverse(new int[]{10, 20, 30, 40}))
            .containsExactly(40, 30, 20, 10);
    }

    @Test void singleElement() {
        assertThat(service.reverse(new int[]{42})).containsExactly(42);
    }

    @Test void emptyArray() {
        assertThat(service.reverse(new int[]{})).isEmpty();
    }

    @Test void twoElements() {
        assertThat(service.reverse(new int[]{1, 2})).containsExactly(2, 1);
    }

    @Test void streamApproach() {
        assertThat(service.reverseStream(new int[]{1, 2, 3, 4, 5}))
            .containsExactly(5, 4, 3, 2, 1);
    }
}
