package com.bank.java8;

import org.junit.jupiter.api.Test;
import java.util.stream.IntStream;
import static org.assertj.core.api.Assertions.assertThat;

class ReverseArrayTest {

    @Test
    void reverseWithoutInbuiltReverse() {
        int[] balances = {100, 200, 300, 400};
        int n = balances.length;

        int[] reversed = IntStream.rangeClosed(1, n)
            .map(i -> balances[n - i])
            .toArray();

        assertThat(reversed).containsExactly(400, 300, 200, 100);
        assertThat(balances).containsExactly(100, 200, 300, 400); // unchanged
    }
}
